using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;

        if (Vector256.IsHardwareAccelerated && values.Length >= Vector256<float>.Count)
        {
            ref float start = ref MemoryMarshal.GetReference(values);

            var acc0 = Vector256.LoadUnsafe(ref start);
            i = Vector256<float>.Count;

            // Two accumulators to hide multiply latency
            var acc1 = Vector256.Create(1f);

            int limit = values.Length - 2 * Vector256<float>.Count + 1;
            for (; i < limit; i += 2 * Vector256<float>.Count)
            {
                acc0 *= Vector256.LoadUnsafe(ref start, (nuint)i);
                acc1 *= Vector256.LoadUnsafe(ref start, (nuint)(i + Vector256<float>.Count));
            }

            acc0 *= acc1;

            for (; i <= values.Length - Vector256<float>.Count; i += Vector256<float>.Count)
                acc0 *= Vector256.LoadUnsafe(ref start, (nuint)i);

            // Horizontal reduction: 8 → 4 → 2 → 1
            var lo = acc0.GetLower();
            var hi = acc0.GetUpper();
            var v128 = lo * hi;
            var shuffled = Vector128.Shuffle(v128, Vector128.Create(2, 3, 0, 1));
            v128 *= shuffled;
            float product = v128[0] * v128[1];

            // Scalar tail
            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        // Scalar fallback with 4x unroll
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int end = values.Length - 3;
        for (; i < end; i += 4)
        {
            p0 *= values[i];
            p1 *= values[i + 1];
            p2 *= values[i + 2];
            p3 *= values[i + 3];
        }
        float result = p0 * p1 * p2 * p3;
        for (; i < values.Length; i++)
            result *= values[i];
        return result;
    }
}

